	public static function takedown_mutation_dto($row){if(!$row||is_wp_error($row))return $row;return array('public_id'=>$row['public_id']??'','status'=>$row['status']??'','version'=>(int)($row['version']??0),'closed_at'=>VWLB_Helpers::iso_utc($row['closed_at']??null));}
}
